import { forwardRef, type ReactNode, type InputHTMLAttributes } from "react";

import { cn } from "@/lib/cn";

/** Props accepted by Input. */
export type InputProps = {
  invalid?: boolean;
} & InputHTMLAttributes<HTMLInputElement>;

/** A styled native text input that preserves caller-owned value and event behavior. */
export const Input = forwardRef<HTMLInputElement, InputProps>(function Input(
  { className, invalid, ...props },
  ref,
) {
  return (
    <input
      {...props}
      aria-invalid={
        invalid
          ? true
          : props["aria-invalid"] === false
            ? undefined
            : props["aria-invalid"]
      }
      className={cn("input caps-input w-full", className)}
      ref={ref}
    />
  );
});

/** A native search input with an optional decorative leading icon. */
export const SearchInput = forwardRef<
  HTMLInputElement,
  InputProps & { leading?: ReactNode }
>(function SearchInput({ leading, className, ...props }, ref) {
  return (
    <span
      className="caps-search-input"
      data-leading={leading ? "true" : undefined}
    >
      {leading ? (
        <span className="caps-search-leading" aria-hidden="true">
          {leading}
        </span>
      ) : null}
      <Input {...props} type="search" className={className} ref={ref} />
    </span>
  );
});

import { STIPE_SPACING_NAMES } from "@fungi.computer/stipe";
import { cva } from "class-variance-authority";
import { createCn } from "cn/config";

/** A conditional class value accepted by cn. */
export type { ClassValue } from "cn";
export { cva };

/** Merge conditional classes with Tailwind rules and Stipe's named spacing. */
export const cn = createCn({
  extend: { theme: { spacing: [...STIPE_SPACING_NAMES] } },
});

/** Resolve a typed React class-name prop before merging its classes. */
export function resolveClassName<State>(
  className: string | ((state: State) => string | undefined) | undefined,
  state: State,
): string | undefined {
  return typeof className === "function" ? className(state) : className;
}

.caps-number-field-input.caps-input.--caps-input-floor:
var(
      --caps-control-number-face,
      color-mix(
        in oklab,
        var(--color-base-200) calc(100% - var(--depth) * 4%),
        var(--color-base-content) calc(var(--depth) * 4%)
      )
    )

