var(
      --caps-control-number-line,
      color-mix(
        in oklab,
        var(--stipe-linework),
        transparent calc(var(--depth) * 100%)
      )
    )

.caps-input,.caps-input:disabled.--caps-input-floor:
color-mix(
      in oklab,
      var(--color-base-200) calc(100% - var(--depth) * 4%),
      var(--color-base-content) calc(var(--depth) * 4%)
    )

.caps-input,.caps-input:disabled.border:
var(--border) solid
      color-mix(
        in oklab,
        var(--stipe-linework),
